for model, layer in targets.items():
    found = False
    for r in data[model]['all_layer_results']:
        if r['layer'] == layer:
            print(f'{model} layer {layer}: bal_acc={r[\"bal_acc\"]}, precision={r[\"precision\"]}')
            found = True
            break
    if not found:
        layers_available = [r['layer'] for r in data[model]['all_layer_results']]
        print(f'{model} layer {layer}: NOT FOUND. Available: {min(layers_available)}-{max(layers_available)} ({len(layers_available)} layers)')
